import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Исходящие подключения","description":"","frontmatter":{},"headers":[],"relativePath":"ru/config/outbound.md","filePath":"ru/config/outbound.md","lastUpdated":1789080411000}`),a={name:`ru/config/outbound.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="исходящие-подключения" tabindex="-1">Исходящие подключения <a class="header-anchor" href="#исходящие-подключения" aria-label="Permalink to “Исходящие подключения”">​</a></h1><p>Исходящие подключения используются для отправки данных. Доступные протоколы см. в разделе <a href="./outbounds/">Исходящие протоколы</a>.</p><h2 id="outboundobject" tabindex="-1">OutboundObject <a class="header-anchor" href="#outboundobject" aria-label="Permalink to “OutboundObject”">​</a></h2><p><code>OutboundObject</code> соответствует дочернему элементу поля <code>outbounds</code> в конфигурационном файле.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Первый элемент в списке используется как основной исходящий узел. Если совпадений с правилами маршрутизации нет или ни одно правило не сработало, трафик отправляется через основной исходящий узел.</p></div><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;outbounds&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;sendThrough&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;0.0.0.0&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;protocol&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;название протокола&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;settings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;tag&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;тег&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;streamSettings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;mux&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;targetStrategy&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;AsIs&quot;</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  ]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><blockquote><p><code>sendThrough</code>: address</p></blockquote><p>IP-адрес, используемый для отправки данных. Этот параметр используется, если на хосте настроено несколько IP-адресов. Значение по умолчанию - <code>&quot;0.0.0.0&quot;</code>.</p><p>Разрешается указывать блок IPv6 CIDR (например, <code>114:514:1919:810::/64</code>). Xray будет использовать случайный IP-адрес из этого блока для установления исходящих соединений. Необходимо правильно настроить сетевое подключение, таблицу маршрутизации и параметры ядра, чтобы разрешить Xray привязываться к любому IP-адресу из этого блока.</p><p>Специальное значение <code>origin</code> — при использовании этого значения запросы будут отправляться с IP-адреса, через который было установлено соединение с локальной машиной.</p><p>Специальное значение <code>srcip</code> — при использовании этого значения запросы будут отправляться с исходного IP-адреса входящего соединения.</p><p>Например, если на машине есть целый блок IPv4-адресов <code>11.4.5.0/24</code> и прослушивается 0.0.0.0 (все IPv4 и IPv6 адреса на сетевой карте), и клиент подключается к локальной машине через <code>11.4.5.14</code>, то исходящие запросы также будут отправляться через <code>11.4.5.14</code>. Если же клиент использует <code>11.4.5.10</code> для подключения к локальной машине, то исходящие запросы будут отправляться через <code>11.4.5.10</code>. То же самое относится и к случаям, когда на машине есть целый блок/несколько IPv6-адресов.</p><p>Как и в описании для <code>inbound</code>, из-за особенностей <code>UDP</code> как протокола без установления соединения, <code>Xray</code> не может определить исходный целевой <code>IP</code>-адрес запроса, поступающего в ядро (например, в рамках одного и того же <code>QUIC</code>-соединения он может даже меняться), поэтому эта функция не может работать.</p><blockquote><p><code>protocol</code>: &quot;blackhole&quot; | &quot;dns&quot; | &quot;freedom&quot; | &quot;http&quot; | &quot;loopback&quot; | &quot;shadowsocks&quot; | &quot;socks&quot; | &quot;trojan&quot; | &quot;vless&quot; | &quot;vmess&quot; | &quot;hysteria&quot; | &quot;wireguard&quot;</p></blockquote><p>Название протокола соединения. Список доступных протоколов см. в разделе <a href="./outbounds/">Исходящие протоколы</a> в меню слева.</p><blockquote><p><code>settings</code>: OutboundConfigurationObject</p></blockquote><p>Конкретные настройки зависят от протокола. См. описание <code>OutboundConfigurationObject</code> для каждого протокола.</p><blockquote><p><code>tag</code>: string</p></blockquote><p>Тег этого исходящего подключения, используемый для идентификации этого подключения в других настройках.</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>Если это поле не пустое, его значение должно быть <strong>уникальным</strong> среди всех тегов.</p></div><blockquote><p><code>streamSettings</code>: <a href="./transport.html">StreamSettingsObject</a></p></blockquote><p>Конфигурация транспорта для этого исходящего подключения.</p><blockquote><p><code>mux</code>: <a href="#muxobject">MuxObject</a></p></blockquote><p>Настройки Mux. Mux позволяет мультиплексировать несколько TCP-соединений через одно TCP-соединение. У Mux есть дополнительная функция: передача UDP-соединений как XUDP.</p><blockquote><p><code>targetStrategy</code>: &quot;AsIs&quot; | &quot;UseIP&quot; | &quot;UseIPv6v4&quot; | &quot;UseIPv6&quot; | &quot;UseIPv4v6&quot; | &quot;UseIPv4&quot; | &quot;ForceIP&quot; | &quot;ForceIPv6v4&quot; | &quot;ForceIPv6&quot; | &quot;ForceIPv4v6&quot; | &quot;ForceIPv4&quot;</p></blockquote><p>Применяется к исходящим подключениям, кроме Freedom. Определяет, нужно ли локально разрешать целевое доменное имя проксируемого запроса в IP и какую стратегию разрешения использовать.</p><p>Значение по умолчанию — <code>AsIs</code>: целевое доменное имя передается на удаленный сервер без изменений. Смысл стратегий в основном совпадает с <code>domainStrategy</code> в <a href="./transports/sockopt.html#sockoptobject">Sockopt</a>.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Здесь контролируются <strong>проксируемые запросы</strong>. Если адресом исходящего прокси-сервера является доменное имя, и для этого домена необходимо выбрать стратегию разрешения, следует настроить <code>domainStrategy</code> в <a href="./transports/sockopt.html#sockoptobject">Sockopt</a>.</p><p>Стратегию разрешения доменных имен для Freedom также следует задавать через <code>sockopt.domainStrategy</code>.</p></div><h3 id="muxobject" tabindex="-1">MuxObject <a class="header-anchor" href="#muxobject" aria-label="Permalink to “MuxObject”">​</a></h3><p>Функция Mux позволяет мультиплексировать несколько TCP-соединений по одному TCP-соединению. Подробнее см. <a href="./../development/protocols/muxcool.html">Mux.Cool</a>. Mux предназначен для сокращения задержек при установлении TCP-соединений, а не для увеличения пропускной способности. Использование Mux при просмотре видео, загрузке файлов или тестировании скорости обычно приводит к обратным результатам. Mux нужно включать только на клиенте, сервер автоматически адаптируется.</p><p><code>MuxObject</code> соответствует полю <code>mux</code> в <code>OutboundObject</code>.</p><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;enabled&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">true</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;concurrency&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">8</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xudpConcurrency&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">16</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xudpProxyUDP443&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;reject&quot;</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><blockquote><p><code>enabled</code>: true | false</p></blockquote><p>Включить пересылку запросов через Mux. Значение по умолчанию - <code>false</code>.</p><blockquote><p><code>concurrency</code>: number</p></blockquote><p>Максимальное количество одновременных соединений. Минимальное значение <code>1</code>, максимальное значение <code>128</code>. Если параметр опущен или задан <code>0</code>, то используется значение <code>8</code>, любые значения больше 128 будут рассматриваться как 128, так как после достижения соединением максимального числа переиспользований (128) ему больше не будут назначаться новые подсоединения. .</p><p>Это значение определяет максимальное количество дочерних соединений, которые могут быть мультиплексированы по одному TCP-соединению. Например, если <code>concurrency</code> равен <code>8</code>, то при отправке 8 TCP-запросов клиентом Xray создаст только одно фактическое TCP-соединение, и все 8 запросов клиента будут передаваться по этому соединению.</p><p>Когда во всех Mux-соединениях исчерпан лимит дочерних соединений, ядро создаст новое соединение для их обслуживания. Если за короткий промежуток времени возникает большое количество одновременных дочерних соединений, число которых затем постепенно снижается, внутренний планировщик ядра будет стремиться распределять запросы между двумя соединениями, используя их попеременно, и оставит остальные соединения простаивать. После того как все дочерние соединения на простаивающих соединениях завершатся естественным образом, они будут закрыты для экономии ресурсов. Если общее количество дочерних соединений продолжает длительное время оставаться ниже значения concurrency, то после того как одно из соединений достигнет максимального числа переиспользований, ядро вернется к режиму одного соединения.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Если указать отрицательное значение, например <code>-1</code>, трафик TCP не будет проходить через Mux.</p></div><blockquote><p><code>xudpConcurrency</code>: number</p></blockquote><p>Использовать новый агрегированный туннель XUDP (т.е. другое Mux-соединение) для проксирования UDP-трафика. Укажите максимальное количество одновременных дочерних UoT-подключений. Минимальное значение - <code>1</code>, максимальное значение - <code>1024</code>. Если этот параметр опущен или равен <code>0</code>, UDP-трафик будет использовать тот же путь, что и TCP-трафик (традиционное поведение).</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Если указать отрицательное значение, например <code>-1</code>, трафик UDP не будет проходить через Mux. Будет использоваться исходный способ передачи UDP-трафика для данного протокола прокси. Например, <code>Shadowsocks</code> будет использовать нативный UDP, а <code>VLESS</code> будет использовать UoT.</p></div><blockquote><p><code>xudpProxyUDP443</code>: string</p></blockquote><p>Управление обработкой проксируемого трафика UDP/443 (QUIC) в Mux:</p><ul><li>По умолчанию <code>reject</code> - отклонять трафик (обычно браузеры автоматически переключаются на TCP HTTP/2).</li><li><code>allow</code> - разрешить трафик через Mux.</li><li><code>skip</code> - не использовать Mux для трафика UDP/443. Будет использоваться исходный способ передачи UDP-трафика для данного протокола прокси. Например, <code>Shadowsocks</code> будет использовать нативный UDP, а <code>VLESS</code> будет использовать UoT.</li></ul>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};